  ('ajustes', 'escuela', '{"titulo":"Aprende a tocar desde los 6 años","intro":"Clases de instrumento y de repertorio y, desde el principio, práctica en grupo con el Bandín.","edad":"Desde los 6 años · También clases para adultos","semana":[{"nombre":"Clase de instrumento","duracion":"45 min","texto":"Clase individual: cada alumno aprende su instrumento con su profesor.","color":"azul"},{"nombre":"Clase de repertorio","duracion":"60 min","texto":"Clase grupal de teoría musical.","color":"verde"},{"nombre":"Ensayo del Bandín","duracion":"60 min","texto":"Todo lo aprendido se pone en práctica tocando juntos.","color":"naranja","enlace":"#bandin","boton":"Conoce el Bandín"}],"cuotasTitulo":"Cuotas de socio promesa","periodo":"trimestre","cuotas":[{"nombre":"Clases de repertorio","precio":"90","color":"azul","destacado":false},{"nombre":"Clases de instrumento","precio":"120","color":"verde","destacado":false},{"nombre":"Repertorio + instrumento","precio":"210","color":"naranja","destacado":true}],"pago":"Cuota trimestral, Domiciliación bancaria"}'::jsonb),
